def parse_config(path: str) -> dict:
    import yaml
    with open(path) as f:
        return yaml.safe_load(f)

import React, { useState } from 'react';
export function Counter() {
  const [n, setN] = useState(0);
  return <button onClick={() => setN(n + 1)}>{n}</button>;
}

